<div class="modulo-cabecalho"><div><h1><i class="fa-solid fa-clock-rotate-left"></i> Histórico de importações</h1><p>Acompanhe resultados, erros e reversões de ficheiros importados.</p></div><a class="btn btn-primary" href="<?php echo URL_BASE; ?>/importacao/index"><i class="fa-solid fa-file-import"></i> Nova importação</a></div><div class="tabela-importacoes"><div class="tabela-scroll"><table><thead><tr><th>Ficheiro</th><th>Data</th><th>Importadas</th><th>Rejeitadas</th><th>Tempo</th><th>Estado</th><th></th></tr></thead><tbody><?php if(empty($importacoes)): ?><tr><td colspan="7" class="sem-resultados">Ainda não existem importações registadas.</td></tr><?php endif; ?><?php foreach($importacoes as $i): ?><tr><td><i class="fa-solid fa-file-excel ficheiro-icone"></i> <?php echo htmlspecialchars($i['nome_arquivo']); ?></td><td><?php echo htmlspecialchars(date('d/m/Y H:i',strtotime($i['criado_em']))); ?></td><td class="numero positivo"><?php echo (int)$i['linhas_importadas']; ?></td><td class="numero negativo"><?php echo (int)$i['linhas_falhadas']; ?></td><td><?php echo isset($i['tempo_processamento_ms']) ? (int)$i['tempo_processamento_ms'].' ms' : '—'; ?></td><td><span class="estado estado-<?php echo htmlspecialchars($i['status']); ?>"><?php echo htmlspecialchars(ucfirst($i['status'])); ?></span></td><td><?php if($i['status']==='concluida'): ?><form method="post" action="<?php echo URL_BASE; ?>/importacao/reverter/<?php echo (int)$i['id']; ?>"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf_token); ?>"><button class="btn btn-outline btn-sm" onclick="return confirm('Reverter os lançamentos desta importação?')"><i class="fa-solid fa-rotate-left"></i> Reverter</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div><style>.tabela-importacoes{background:#fff;border:1px solid var(--border);border-radius:14px;overflow:hidden}.tabela-scroll{overflow:auto}.tabela-importacoes table{border-collapse:collapse;width:100%;font-size:13px}.tabela-importacoes th{background:var(--navy-deep);color:#fff;text-align:left;padding:12px}.tabela-importacoes td{padding:13px 12px;border-bottom:1px solid var(--border)}.numero{text-align:right;font-weight:700}.positivo{color:var(--green-dark)}.negativo{color:var(--red)}.ficheiro-icone{color:#1d6f42}.estado{padding:4px 9px;border-radius:99px;font-weight:700;font-size:11px}.estado-concluida{background:rgba(34,197,94,.12);color:var(--green-dark)}.estado-processando{background:#fff3cd;color:#8a6510}.estado-falhou{background:rgba(239,68,68,.1);color:var(--red)}.estado-revertida{background:#edf0f4;color:var(--muted)}.sem-resultados{text-align:center;color:var(--muted);padding:32px!important}</style>
